/**
 * Assistant thread UX: titles and suggested prompts.
 */
import { setSuggestedPrompts, setThreadTitle, truncateTitle } from "./api.js";
import { defaultSlackLog } from "./log.js";
export function firstNonEmptyLine(text) {
    for (const line of text.split(/\r?\n/u)) {
        const trimmed = line.trim();
        if (trimmed.length > 0) {
            return trimmed;
        }
    }
    return undefined;
}
export function firstLineTitle(text) {
    return truncateTitle(firstNonEmptyLine(text) ?? "Conversation");
}
export async function maybeSetThreadTitle(args) {
    const log = args.log ?? defaultSlackLog;
    const result = await setThreadTitle({
        botToken: args.botToken,
        channelId: args.channelId,
        threadTs: args.threadTs,
        title: args.title,
    });
    if (!result.ok) {
        log.warn("setTitle not-ok", {
            error: result.error,
            channel: args.channelId,
            thread_ts: args.threadTs,
        });
        return false;
    }
    return true;
}
export async function maybeSetSuggestedPrompts(args) {
    const log = args.log ?? defaultSlackLog;
    if (args.prompts.length === 0) {
        return false;
    }
    const result = await setSuggestedPrompts({
        botToken: args.botToken,
        channelId: args.channelId,
        threadTs: args.threadTs,
        prompts: args.prompts,
        ...(args.title === undefined ? {} : { title: args.title }),
    });
    if (!result.ok) {
        log.warn("setSuggestedPrompts not-ok", {
            error: result.error,
            channel: args.channelId,
            thread_ts: args.threadTs,
        });
        return false;
    }
    return true;
}
